#!/usr/bin/env bash
# Minimal systemctl shim for a container environment without a running systemd.
# Maps the service names used by Qisutu (apache2, mariadb, *-daemon.service,
# *-install-complete.path/.service) to direct process management.
# Every call is appended to /var/log/qisutu-systemctl-shim.log.
LOG=/var/log/qisutu-systemctl-shim.log
STATE=/run/qisutu/systemctl.state
mkdir -p /run/qisutu
echo "[$(date '+%F %T')] systemctl $*" >>"$LOG"

